BEGIN TRANSACTION;
CREATE TABLE patients (
    patient_id TEXT PRIMARY KEY,
    mrn TEXT UNIQUE,
    patient_name TEXT,
    age INTEGER,
    gender TEXT,
    avg_velocity REAL,
    avg_jerk REAL,
    pressure_std REAL,
    in_air_time_ratio REAL,
    mean_f0_hz REAL,
    jitter_percent REAL,
    shimmer_local REAL,
    hnr_db REAL,
    step_cadence_spm REAL,
    stride_time_variance REAL,
    arm_swing_asymmetry_index REAL,
    upsit_smell_score REAL,
    rbd_sleep_flag INTEGER
);
COMMIT;
